import React from 'react';
import { ShieldAlert } from 'lucide-react';

/**
 * İlaç Arınma Süresi (Withdrawal Period) Güvenlik Alarmı
 * İlaç alan hayvanın süt veya etinin insan tüketimine sunulmasını engelleyen yasal güvenlik kilidi.
 */
export default function WithdrawalAlertBadge({ healthRecords = [], compact = false }) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Aktif arınma süresinde olan kayıtları bul
  const activeWithdrawals = healthRecords.filter(record => {
    if (!record || record.record_type !== 'medication') return false;
    // Eğer next_date veya withdrawal_end_date varsa ve bugünden sonraysa
    const withdrawalDate = record.withdrawal_end_date || record.next_date;
    if (!withdrawalDate) return false;
    const end = new Date(withdrawalDate);
    end.setHours(0, 0, 0, 0);
    return end >= today;
  });

  if (activeWithdrawals.length === 0) return null;

  const latest = activeWithdrawals[0];
  const endDate = new Date(latest.withdrawal_end_date || latest.next_date);
  const diffDays = Math.ceil((endDate - today) / (1000 * 60 * 60 * 24));

  if (compact) {
    return (
      <span 
        className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-700 border border-rose-300 animate-pulse"
        title={`İlaç Arınma Süresi Devam Ediyor: ${latest.medication_name || 'İlaç'} (Son: ${endDate.toLocaleDateString('tr-TR')})`}
      >
        <ShieldAlert className="w-3 h-3 text-rose-600" />
        SÜT/ET KİLİTLİ ({diffDays} gün)
      </span>
    );
  }

  return (
    <div className="bg-rose-50 border-l-4 border-rose-600 p-3.5 rounded-xl shadow-xs flex items-start gap-3 my-2 animate-in fade-in">
      <div className="p-2 bg-rose-600 text-white rounded-lg flex-shrink-0 mt-0.5">
        <ShieldAlert className="w-5 h-5" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <p className="font-bold text-rose-900 text-sm">
            ⚠️ Yasal İlaç Arınma Süresi (Süt/Et Satışı Yasaktır)
          </p>
          <span className="px-2 py-0.5 rounded text-[10px] font-black bg-rose-200 text-rose-900 uppercase">
            {diffDays} Gün Kaldı
          </span>
        </div>
        <p className="text-xs text-rose-800 mt-1 leading-relaxed">
          Kullanılan İlaç: <strong className="font-semibold">{latest.medication_name || 'Klinik Tedavi'}</strong>. 
          Gıda güvenliği gereği <strong>{endDate.toLocaleDateString('tr-TR')}</strong> tarihine kadar sağılan süt veya kesim eti tüketime verilemez.
        </p>
      </div>
    </div>
  );
}
